 const theme=themes[type]||themes.meadow;const boardExtent=Math.max(3,...level.board.cells.map(c=>Math.max(Math.abs(c.q),Math.abs(c.r),Math.abs(c.q+c.r))));const terrainRadius=Math.floor(Math.max(24,Math.min(42,radius*1.5)));scene.background=new THREE.Color(theme.sky);scene.fog=new THREE.Fog(theme.fog,18,Math.max(76,terrainRadius*2.7));
