 const addTree=(x:number,z:number,scale:number,leaf:string)=>{const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.07*scale,.11*scale,.55*scale,5),mat('#735947'));trunk.position.set(x,-.35+.25*scale,z);scenery.add(trunk);const crown=new THREE.Mesh(new THREE.ConeGeometry(.42*scale,.9*scale,6),mat(leaf));crown.position.set(x,-.02+.45*scale,z);crown.castShadow=true;scenery.add(crown);};
 const addHouse=(x:number,z:number,scale:number,wall:string,roof:string)=>{const body=new THREE.Mesh(new THREE.BoxGeometry(.95*scale,.72*scale,.82*scale),mat(wall));body.position.set(x,-.25+.36*scale,z);body.castShadow=true;scenery.add(body);const roofMesh=new THREE.Mesh(new THREE.ConeGeometry(.78*scale,.58*scale,4),mat(roof));roofMesh.rotation.y=Math.PI/4;roofMesh.position.set(x,.32*scale,z);roofMesh.castShadow=true;scenery.add(roofMesh);const door=new THREE.Mesh(new THREE.BoxGeometry(.18*scale,.34*scale,.035),mat('#4c3b39'));door.position.set(x,-.32+.17*scale,z+.42*scale);scenery.add(door);};
 const count=type==='smallVillage'?8:type==='medievalCastle'?7:type==='witchHut'?9:type==='snowMountain'?11:type==='temple'?9:((type==='meadow'||type==='hills')?Math.floor(radius*1.5):0);
 for(let i=0;i<count;i++){const a=(i/count)*Math.PI*2+(rand()-.5)*.18,d=ringRadius+rand()*1.5,x=Math.cos(a)*d,z=Math.sin(a)*d,sc=.75+rand()*.55;
  if(theme.kind==='village')addHouse(x,z,sc,['#dfc99e','#c9b78f','#d8b9a0'][i%3],['#a65e4d','#7d5a4b','#b78b56'][i%3]);
  else if(theme.kind==='witch'){if(i===0){addHouse(x,z,sc,'#5c5949','#44334f');const hat=new THREE.Mesh(new THREE.ConeGeometry(.7*sc,.9*sc,7),mat('#30253d'));hat.position.set(x,1.05*sc,z);hat.rotation.z=.18;scenery.add(hat);}else addTree(x,z,sc,i%2?'#3c5948':'#51415f');}
  else if(theme.kind==='meadow'||theme.kind==='hills')addTree(x,z,sc,i%2?'#477c66':'#6c9a76');
  else if(theme.kind==='snow'){const peak=new THREE.Mesh(new THREE.ConeGeometry(.8*sc,2.5*sc,5),mat(i%2?'#eef7ff':'#9dbbd0'));peak.position.set(x,.7*sc,z);peak.castShadow=true;scenery.add(peak);}
  else if(theme.kind==='castle'){const tower=new THREE.Mesh(new THREE.CylinderGeometry(.42*sc,.5*sc,2.1*sc,8),mat(i%2?'#8996a2':'#697784'));tower.position.set(x,.45*sc,z);tower.castShadow=true;scenery.add(tower);const roof=new THREE.Mesh(new THREE.ConeGeometry(.48*sc,.65*sc,8),mat('#59616f'));roof.position.set(x,1.8*sc,z);scenery.add(roof);}
  else if(theme.kind==='temple'){const col=new THREE.Mesh(new THREE.CylinderGeometry(.18*sc,.23*sc,1.8*sc,6),mat('#d5bd8d'));col.position.set(x,.35*sc,z);col.castShadow=true;scenery.add(col);const cap=new THREE.Mesh(new THREE.BoxGeometry(.62*sc,.16*sc,.62*sc),mat('#ead7ae'));cap.position.set(x,1.3*sc,z);scenery.add(cap);}
 }
 // Layered low-poly silhouettes create a distant horizon beyond the scattered hex field.
 const horizonCount=type==='snowMountain'?34:26;
 for(let i=0;i<horizonCount;i++){const a=(i/horizonCount)*Math.PI*2+(rand()-.5)*.12;const d=terrainRadius*.7+rand()*terrainRadius*.18;const h=type==='snowMountain'?5+rand()*8:type==='hills'||type==='meadow'?2.2+rand()*4:type==='lavaLake'?3+rand()*5:2.5+rand()*5;const w=(type==='snowMountain'?1.5:1.1)+rand()*2;const ridgeColor=type==='snowMountain'?(rand()>.45?'#b5cfe0':'#e6f1f8'):type==='lavaLake'?(rand()>.5?'#453b43':'#5d4144'):type==='witchHut'?(rand()>.5?'#45405c':'#5c4d6a'):theme.palette[Math.floor(rand()*theme.palette.length)];const ridge=new THREE.Mesh(new THREE.ConeGeometry(w,h,5,1),mat(ridgeColor,.94));ridge.position.set(Math.cos(a)*d,-.7+h*.38,Math.sin(a)*d);ridge.rotation.y=rand()*Math.PI;ridge.scale.set(1+rand()*.6,1,1+rand()*.6);ridge.castShadow=false;ridge.receiveShadow=true;scenery.add(ridge);}
 if(theme.kind==='lava'){for(let i=0;i<12;i++){const m=new THREE.Mesh(new THREE.TorusGeometry(2+rand()*7,.035+rand()*.05,5,40),new THREE.MeshBasicMaterial({color:i%2?'#e45c35':'#ff9d45',transparent:true,opacity:.22}));m.rotation.x=Math.PI/2;m.position.set((rand()-.5)*3,-.48,(rand()-.5)*3);scenery.add(m);}}
 if(theme.kind==='meadow'||theme.kind==='hills'||theme.kind==='village'){
  for(let i=0;i<Math.floor(radius*2.4);i++){const a=rand()*Math.PI*2,d=4.2+rand()*Math.max(1,radius-4),x=Math.cos(a)*d,z=Math.sin(a)*d,s=.12+rand()*.12;const stem=new THREE.Mesh(new THREE.CylinderGeometry(.018,.028,s*2.2,5),mat('#456c4d'));stem.position.set(x,-.42+s,z);scenery.add(stem);const flowerColor=['#f5d6a0','#f2a8a4','#d9c5ff','#fff0d0'][Math.floor(rand()*4)];const bloom=new THREE.Mesh(new THREE.SphereGeometry(s,8,6),mat(flowerColor));bloom.scale.set(1,.62,1);bloom.position.set(x,-.35+s*2.2,z);scenery.add(bloom);}
 }
 // Fireflies / snow glints are render-only particles with deterministic positions.
 const moteMat=new THREE.MeshBasicMaterial({color:theme.accent,transparent:true,opacity:.68});
 for(let i=0;i<24;i++){const mote=new THREE.Mesh(new THREE.SphereGeometry(.035+rand()*.025,6,5),moteMat);const a=rand()*Math.PI*2,d=2.8+rand()*Math.max(1,radius-2);mote.position.set(Math.cos(a)*d,.35+rand()*2.8,Math.sin(a)*d);mote.userData.floatPhase=rand()*Math.PI*2;mote.userData.baseY=mote.position.y;scenery.add(mote);}
