function screenDirection(keyName:string):{q:number;r:number}{
 const desired:Record<string,THREE.Vector2>={w:new THREE.Vector2(0,1),s:new THREE.Vector2(0,-1),a:new THREE.Vector2(-1,0),d:new THREE.Vector2(1,0)};const target=desired[keyName];if(!target)return {q:0,r:0};
 camera.updateMatrixWorld();const inverse=camera.quaternion.clone().invert();let best=DIRS[0],bestScore=-Infinity;
 for(const dir of DIRS){const v=new THREE.Vector3((dir.q+dir.r*.5)*Math.sqrt(3),0,dir.r*1.5).applyQuaternion(inverse);const screen=new THREE.Vector2(v.x,v.y).normalize();const score=screen.dot(target);if(score>bestScore){bestScore=score;best=dir;}}return {q:best.q,r:best.r};
}
function axialName(d:{q:number;r:number}){const names=['E','NE','NW','W','SW','SE'];const idx=DIRS.findIndex(x=>x.q===d.q&&x.r===d.r);return names[idx]||'?';}
function updateDirectionReadout(){const el=document.querySelector('#directionReadout');if(!el)return;el.textContent=`W ${axialName(screenDirection('w'))} · A ${axialName(screenDirection('a'))} · S ${axialName(screenDirection('s'))} · D ${axialName(screenDirection('d'))}`;}
controls.addEventListener('change',updateDirectionReadout);
function updateHud(){document.querySelector('#levelName')!.textContent=level.metadata.name;document.querySelector('#moveCount')!.textContent=String(moves);document.querySelector('#moveLimit')!.textContent=level.rules.moveLimitEnabled===false?'∞':String(level.rules.moveLimit);document.querySelector('#plateStatus')!.textContent=level.objectives.requiredPlateIds.every(id=>{const p=objects.find(o=>o.id===id);return !!p&&isPlateActive(p);})?'✓':'○';const requiredReceivers=level.objectives.requiredReceiverIds??[];document.querySelector('#receiverObjective')!.classList.toggle('hidden',requiredReceivers.length===0);document.querySelector('#receiverStatus')!.textContent=requiredReceivers.every(id=>objects.some(o=>o.id===id&&o.type==='receiver'&&o.active))?'✓':'○';const requiredKeys=level.objectives.requiredKeyIds??[];document.querySelector('#keyObjective')!.classList.toggle('hidden',requiredKeys.length===0);document.querySelector('#requiredKeyStatus')!.textContent=requiredKeys.every(id=>objects.some(o=>o.id===id&&o.type==='key'&&o.active))?'✓':'○';document.querySelector('#goalStatus')!.textContent=won?'✓':'○';document.querySelector('#moveBar')!.setAttribute('style',`width:${level.rules.moveLimitEnabled===false?0:Math.min(100,moves/Math.max(1,level.rules.moveLimit)*100)}%`);document.querySelector('#hintText')!.textContent=won?'Puzzle complete. Restart to play again or open the editor to modify this level.':`Click a block to attach. While attached, movement is locked until a key is collected. Rotations are free. ${keyCount} keys · ${level.rules.moveLimitEnabled===false?'unlimited':Math.max(0,level.rules.moveLimit-moves)} walking moves remain.`;const oldKeys=document.querySelector('#keyCount');if(oldKeys)oldKeys.textContent=String(keyCount);}
function capture():Snapshot{return {level:structuredClone(level),player:structuredClone(player),objects:structuredClone(objects),attached:[...attached],moves,won,keyCount};}
function restore(s:Snapshot){level=structuredClone(s.level);player=structuredClone(s.player);objects=structuredClone(s.objects);attached=new Set(s.attached);moves=s.moves;won=s.won;keyCount=s.keyCount??0;if(editorMode!=='play')baseLevel=normalizeLevel(structuredClone(level));drawBoard();drawEnvironment();updateHud();}
function pushUndo(){undoStack.push(capture());if(undoStack.length>100)undoStack.shift();redoStack.length=0;}
function undo(){if(!undoStack.length){say('Nothing to undo.');return;}redoStack.push(capture());restore(undoStack.pop()!);recordRunFrame('undo');say('Action undone.');}
function redo(){if(!redoStack.length){say('Nothing to redo.');return;}undoStack.push(capture());restore(redoStack.pop()!);recordRunFrame('redo');say('Action redone.');}
function snapWorld(){const p=hexWorld(player);const pg=objectMeshes.get('player');if(pg)pg.position.copy(p);for(const o of objects){const g=objectMeshes.get(o.id);if(g)g.position.copy(hexWorld(o));}}
function isGateOpen(o:LevelObject){return isLinkedMechanismOpen(o,objects)||(o.requiresKey===true&&keyCount>0);}
function occupied(p:Hex,ignoreIds:string[]=[]){if(!hasCell(p))return true;return objects.some(o=>{if(ignoreIds.includes(o.id)||o.q!==p.q||o.r!==p.r||o.h!==p.h)return false;if(['block','wall'].includes(o.type))return true;if(o.type==='gate')return !isGateOpen(o);if(o.type==='bridge')return !isLinkedMechanismOpen(o,objects)&&o.kind!=='normallyOpen';return false;});}
function isLaserHazard(p:Hex){return objects.filter(o=>o.type==='laser').some(l=>traceLaser(level,objects,l).cells.some(c=>sameHex(c,p)));}
function gravity(){const result=resolveGravity(level,objects,attached);objects=result.objects;for(const id of result.detachedIds){attached.delete(id);say(`${id} dropped to a lower platform and detached.`);}for(const id of result.fallenIds){attached.delete(id);say(`${id} fell into the void.`);}level.objects=[structuredClone(player),...structuredClone(objects)];}
function checkWin(){refreshReceiverStates(level,objects);const plates=level.objectives.requiredPlateIds.every(id=>{const p=objects.find(o=>o.id===id);return !!p&&isPlateActive(p);});const receivers=(level.objectives.requiredReceiverIds??[]).every(id=>objects.some(o=>o.id===id&&o.type==='receiver'&&o.active));const keys=(level.objectives.requiredKeyIds??[]).every(id=>objects.some(o=>o.id===id&&o.type==='key'&&o.active));if(plates&&receivers&&keys&&player.q===Number(objects.find(o=>o.id===level.objectives.goalId)?.q)&&player.r===Number(objects.find(o=>o.id===level.objectives.goalId)?.r)&&player.h===Number(objects.find(o=>o.id===level.objectives.goalId)?.h)){won=true;say('Puzzle complete. Exit reached.');chirp(880,.2,'triangle');recordRunFrame('complete');showCompletionModal();updateHud();return true;}return false;}
function playerCanStand(p:Hex){const c=cellAt(p);if(!c||c.kind==='void'||c.support===false)return objects.some(o=>o.type==='bridge'&&o.q===p.q&&o.r===p.r&&o.h===p.h&&isLinkedMechanismOpen(o,objects));return true;}
function applyTileMechanics(){
 const here=objects.find(o=>o.type==='conveyor'&&o.q===player.q&&o.r===player.r&&o.h===player.h);
 if(here){const d=DIRS[((here.direction??0)%6+6)%6];const next={q:player.q+d.q,r:player.r+d.r,h:player.h};const carried=objects.filter(o=>attached.has(o.id));const ignore=carried.map(o=>o.id);const translated=carried.map(o=>({...o,q:o.q+d.q,r:o.r+d.r}));if(playerCanStand(next)&&!occupied(next,ignore)&&!isLaserHazard(next)&&translated.every(o=>!occupied(o,ignore)&&!isLaserHazard(o))){player.q=next.q;player.r=next.r;for(const n of translated){const original=objects.find(o=>o.id===n.id)!;original.q=n.q;original.r=n.r;}say('Conveyor carried you one hex.');}}
 const portal=objects.find(o=>o.type==='teleporter'&&o.q===player.q&&o.r===player.r&&o.h===player.h);
 if(portal?.linkedTo){const target=objects.find(o=>o.type==='teleporter'&&o.id===portal.linkedTo);if(target){const dq=target.q-player.q,dr=target.r-player.r,dh=target.h-player.h;const carried=objects.filter(o=>attached.has(o.id));const ignore=carried.map(o=>o.id);const translated=carried.map(o=>({...o,q:o.q+dq,r:o.r+dr,h:o.h+dh}));const dest={q:target.q,r:target.r,h:target.h};if(playerCanStand(dest)&&!occupied(dest,ignore)&&translated.every(o=>!occupied(o,ignore))){player.q=target.q;player.r=target.r;player.h=target.h;for(const n of translated){const original=objects.find(o=>o.id===n.id)!;original.q=n.q;original.r=n.r;original.h=n.h;}say('Teleporter activated.');chirp(760,.12,'sine');}}}
 const toggle=objects.find(o=>o.type==='switch'&&o.q===player.q&&o.r===player.r&&o.h===player.h);if(toggle){toggle.active=!toggle.active;say(`${toggle.id} switched ${toggle.active?'on':'off'}.`);chirp(toggle.active?680:360,.09,'triangle');}
}
function recordRunFrame(action:string){if(!runFrames)runFrames=[];runFrames.push({index:runFrames.length,action,elapsedMs:Date.now()-runStartedAt,player:structuredClone(player),objects:structuredClone(objects),attached:[...attached],moves,keyCount,won});}
function downloadRunRecording(){const payload={format:'ishibako-run-recording',version:1,level:{id:level.metadata.id,name:level.metadata.name,seed:level.environment.seed},initialLevel:baseLevel,startedAt:new Date(runStartedAt).toISOString(),completed:won,frames:runFrames};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${level.metadata.id||'ishibako'}-run-${new Date(runStartedAt).toISOString().replace(/[:.]/g,'-')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function showCompletionModal(){const modal=document.querySelector('#completionModal');modal?.classList.remove('hidden');}
function move(d:{q:number;r:number}){if(won||busy||editorMode!=='play')return;if(attached.size>0&&keyCount===0){say('You are anchored to the attached block. Collect a key to regain movement.');chirp(180,.05);return;}if(level.rules.moveLimitEnabled!==false&&moves>=level.rules.moveLimit){say('Move limit reached. Restart to try again.');chirp(130,.1,'square');return;}const next={q:player.q+d.q,r:player.r+d.r,h:player.h};const carried=objects.filter(o=>attached.has(o.id));const ignore=carried.map(o=>o.id);if(occupied(next,ignore)||!playerCanStand(next)){say('That hex is blocked or has no floor.');chirp(180,.05);return;}if(isLaserHazard(next)){say('An active laser blocks that hex.');chirp(180,.05);return;}const newPositions=carried.map(o=>({...o,q:o.q+d.q,r:o.r+d.r}));if(newPositions.some(o=>occupied(o,ignore)||isLaserHazard(o))){say('The attached assembly cannot pass through that space.');chirp(180,.05);return;}pushUndo();const previousPlayer={q:player.q,r:player.r,h:player.h};player.q=next.q;player.r=next.r;for(const n of newPositions){const o=objects.find(o=>o.id===n.id)!;o.q=n.q;o.r=n.r;}const foundKey=objects.find(o=>o.type==='key'&&!o.active&&o.q===player.q&&o.r===player.r&&o.h===player.h);if(foundKey){foundKey.active=true;keyCount++;say(`Key collected. ${keyCount} key${keyCount===1?'':'s'} found. Movement is unlocked while attached.`);chirp(820,.15,'triangle');}moves++;const oldCell=cellAt(previousPlayer);if(oldCell?.kind==='fragile'){oldCell.support=false;oldCell.kind='void';}applyTileMechanics();gravity();level.objects=[structuredClone(player),...structuredClone(objects)];chirp(320,.055,'sine');drawBoard();recordRunFrame('move');checkWin();}
function rotateAttached(sign:number){if(won||busy||editorMode!=='play')return;const blocks=objects.filter(o=>attached.has(o.id));if(!blocks.length){say('Click an adjacent block to attach it first.');return;}const moved=blocks.map(o=>{const dq=o.q-player.q,dr=o.r-player.r; // 60-degree axial rotation
 const q=sign===1?-dr:dq+dr; const r=sign===1?dq+dr:-dq; return {o,q:player.q+q,r:player.r+r,h:o.h};});
 if(moved.some(m=>occupied(m,[...attached])||isLaserHazard(m))){say('Rotation blocked by the board or another block.');chirp(160,.06);return;}
 pushUndo();for(const m of moved){m.o.q=m.q;m.o.r=m.r;}gravity();level.objects=[structuredClone(player),...structuredClone(objects)];chirp(sign>0?500:420,.09,'triangle');drawBoard();recordRunFrame(sign>0?'rotate-clockwise':'rotate-counterclockwise');checkWin();say('Assembly rotated. No walking move spent.');}
function toggleAttach(id:string){if(won||editorMode!=='play')return;const o=objects.find(o=>o.id===id&&o.type==='block');if(!o)return;const members=assemblyMembers(objects,id);const ids=members.map(m=>m.id);const isAttached=ids.every(memberId=>attached.has(memberId));if(isAttached){pushUndo();ids.forEach(memberId=>attached.delete(memberId));say(members.length>1?'Glued assembly detached.':'Block detached.');}else{if(hexDistance(player,o)!==1||player.h!==o.h){say('Move next to a block to attach it.');return;}pushUndo();ids.forEach(memberId=>attached.add(memberId));say(members.length>1?`Attached glued assembly (${members.length} blocks).`:`Attached ${id}. Walk to carry it, or press Q / E to rotate.`);}chirp(isAttached?280:600,.07,'triangle');drawBoard();recordRunFrame(isAttached?'detach':'attach');}
function restart(){undoStack.length=0;redoStack.length=0;moves=0;won=false;keyCount=0;attached.clear();runFrames=[];runStartedAt=Date.now();level=normalizeLevel(structuredClone(baseLevel));player=level.objects.find(o=>o.type==='player')!;objects=level.objects.filter(o=>o.type!=='player');keyCount=objects.filter(o=>o.type==='key'&&o.active).length;recordRunFrame('start');drawBoard();say('Level restarted.');}
function useLift(){if(won||editorMode!=='play')return;const lift=objects.find(o=>o.type==='lift'&&o.q===player.q&&o.r===player.r&&o.h===player.h);if(!lift){say('Stand on a lift platform, then press F.');return;}const target=objects.find(o=>o.type==='lift'&&o.id===lift.linkedTo);if(!target){say('This lift has no linked destination. Set linkedTo to another lift ID.');return;}if(lift.enabledBy&&!isLinkedMechanismOpen(lift,objects)){say(`Lift is disabled until ${lift.enabledBy} is activated.`);return;}if(level.rules.moveLimitEnabled!==false&&moves>=level.rules.moveLimit){say('Move limit reached. Restart to try again.');return;}const dh=target.h-player.h,dq=target.q-player.q,dr=target.r-player.r;const carried=objects.filter(o=>attached.has(o.id));const ignore=carried.map(o=>o.id);const destination={q:target.q,r:target.r,h:target.h};if(!hasCell(destination)||occupied(destination,ignore)){say('Lift destination is blocked.');return;}const translated=carried.map(o=>({...o,q:o.q+dq,r:o.r+dr,h:o.h+dh}));if(translated.some(o=>occupied(o,ignore)||isLaserHazard(o))){say('The attached assembly cannot fit at the destination.');return;}pushUndo();player.q=target.q;player.r=target.r;player.h=target.h;for(const moved of translated){const original=objects.find(o=>o.id===moved.id)!;original.q=moved.q;original.r=moved.r;original.h=moved.h;}moves++;gravity();level.objects=[structuredClone(player),...structuredClone(objects)];drawBoard();recordRunFrame('lift');checkWin();say('Lift transfer complete. One walking move spent.');chirp(700,.12,'sine');}
let baseLevel=normalizeLevel(structuredClone(starterLevel));
function loadLevel(input:unknown){const normalized=normalizeLevel(input as Level);const errors=validateLevel(normalized);const val=document.querySelector<HTMLDivElement>('#validation');if(errors.length){if(val)val.textContent='Cannot apply: '+errors.join(' ');say('Level JSON has validation errors.');return;}level=normalized;baseLevel=normalizeLevel(structuredClone(normalized));selectedObjectId=null;musicCustom=false;configureBiomeMusic();undoStack.length=0;redoStack.length=0;player=level.objects.find(o=>o.type==='player')!;objects=level.objects.filter(o=>o.type!=='player');moves=0;won=false;keyCount=objects.filter(o=>o.type==='key'&&o.active).length;attached.clear();runFrames=[];runStartedAt=Date.now();recordRunFrame('start');drawBoard();drawEnvironment();fitCamera();if(val)val.textContent='Level applied and validated.';say(level.metadata.description||`Loaded: ${level.metadata.name}`);}
function fitCamera(){const rad=level.board.radius||3;camera.position.set(rad*2.2+2,rad*2.7+2,rad*2.7+3);controls.target.set(0,0,0);controls.update();}
function exportJson(){const data=JSON.stringify(level,null,2);const blob=new Blob([data],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${level.metadata.id||'ishibako-level'}.json`;a.click();URL.revokeObjectURL(url);}
function applyEditorTool(cell:Hex){const tool=editorMode;const h=Number((document.querySelector<HTMLInputElement>('#editorElevation')!).value)||0;const p={q:cell.q,r:cell.r,h};
 if(tool==='play'){return;}
 if(tool==='eraseCell'){if(level.board.cells.length<=1){say('A board must keep at least one cell.');return;}pushUndo();level.board.cells=level.board.cells.filter(c=>!(c.q===cell.q&&c.r===cell.r&&c.h===cell.h));objects=objects.filter(o=>!(o.q===cell.q&&o.r===cell.r&&o.h===cell.h));if(player.q===cell.q&&player.r===cell.r&&player.h===cell.h){const replacement=level.board.cells[0];if(replacement){player.q=replacement.q;player.r=replacement.r;player.h=replacement.h;}}level.objects=[structuredClone(player),...structuredClone(objects)];baseLevel=normalizeLevel(structuredClone(level));drawBoard();drawEnvironment();syncEditor();say('Cell and any objects on it removed.');return;}
 if(tool==='cell'){pushUndo();const candidate={q:cell.q+1,r:cell.r,h};if(!level.board.cells.some(c=>c.q===candidate.q&&c.r===candidate.r&&c.h===candidate.h))level.board.cells.push(candidate);level.board.radius=Math.max(level.board.radius,Math.abs(candidate.q),Math.abs(candidate.r),Math.abs(candidate.q+candidate.r));level.objects=[structuredClone(player),...structuredClone(objects)];baseLevel=normalizeLevel(structuredClone(level));drawBoard();drawEnvironment();syncEditor();say('Added a cell one hex east of the selected tile.');return;}
 if(!['player','block','plate','goal','wall','gate','lift','bridge','laser','mirror','receiver','key','conveyor','teleporter','switch'].includes(tool))return;
 if(!hasCell(p)){say('Choose an existing tile at the selected elevation first.');return;}
 if(tool==='player'){pushUndo();player={...player,q:p.q,r:p.r,h:p.h};level.objects=[structuredClone(player),...structuredClone(objects)];baseLevel=normalizeLevel(structuredClone(level));drawBoard();syncEditor();say('Player spawn moved.');return;}
 if(['block','wall','gate','bridge'].includes(tool)&&objects.some(o=>o.q===p.q&&o.r===p.r&&o.h===p.h&&['block','wall','gate','bridge'].includes(o.type))){say('That tile already contains a solid object.');return;}
 pushUndo();const id=`${tool}-${Math.max(0,...objects.map(o=>Number(o.id.match(/(\d+)$/)?.[1]||0)))+1}`;if(tool==='goal')objects=objects.filter(o=>o.type!=='goal');objects.push({id,type:tool as LevelObject['type'],...p,color:tool==='block'?'#f0b45b':tool==='plate'?'#5de0c1':tool==='goal'?'#a6a1ff':tool==='laser'?'#ff526f':tool==='mirror'?'#9bd8e4':tool==='key'?'#ffe58a':undefined,direction:0});level.objects=[structuredClone(player),...structuredClone(objects)];baseLevel=normalizeLevel(structuredClone(level));drawBoard();syncEditor();say(`Placed ${tool} at (${p.q}, ${p.r}, ${p.h}).`);
}
function rotateSelectedObject(){const obj=objects.find(o=>o.id===selectedObjectId);if(!obj||!['laser','mirror'].includes(obj.type)){say('Select a laser emitter or mirror in the scene first.');return;}pushUndo();obj.direction=((obj.direction??0)+1)%6;level.objects=[structuredClone(player),...structuredClone(objects)];drawBoard();syncEditor();say(`${obj.type} direction: ${obj.direction} (${axialName(DIRS[obj.direction])}).`);}
function updateSelectedObjectNote(){const el=document.querySelector('#selectedObjectNote');const obj=objects.find(o=>o.id===selectedObjectId);if(el)el.textContent=obj?`Selected: ${obj.id} · ${obj.type} · tile (${obj.q}, ${obj.r}, height ${obj.h}) · direction ${obj.direction??'n/a'}`:'No object selected.';}
function syncConnections(){const root=document.querySelector<HTMLDivElement>('#connectionCards');if(!root)return;const sources=objects.filter(o=>['plate','receiver','key','lift','switch','teleporter'].includes(o.type));const targets=objects.filter(o=>['gate','bridge','lift','teleporter'].includes(o.type));root.innerHTML='';if(!sources.length||!targets.length){root.innerHTML='<span class="connection-empty">Add a pressure plate, receiver, key or lift, then add a gate, bridge or lift to connect them.</span>';return;}
 const sourceWrap=document.createElement('div');sourceWrap.className='connection-source-list';const targetWrap=document.createElement('div');targetWrap.className='connection-target-list';const makeChip=(o:LevelObject,source:boolean)=>{const chip=document.createElement('div');chip.className='connection-chip '+(source?'source':'target');chip.textContent=`${source?'↗':'⇩'} ${o.id} · ${o.type}`;chip.dataset.objectId=o.id;if(source){chip.draggable=true;chip.addEventListener('dragstart',e=>e.dataTransfer?.setData('text/ishibako-source',o.id));chip.title='Drag onto a target to connect';}else{chip.addEventListener('dragover',e=>{e.preventDefault();chip.classList.add('drop-ready');});chip.addEventListener('dragleave',()=>chip.classList.remove('drop-ready'));chip.addEventListener('drop',e=>{e.preventDefault();chip.classList.remove('drop-ready');const sourceId=e.dataTransfer?.getData('text/ishibako-source');if(!sourceId)return;const sourceObj=objects.find(x=>x.id===sourceId);const targetObj=objects.find(x=>x.id===o.id);if(!sourceObj||!targetObj)return;if(sourceObj.id===targetObj.id){say('An object cannot be connected to itself.');return;}if(targetObj.type==='lift'&&sourceObj.type==='lift'){pushUndo();targetObj.linkedTo=sourceId;sourceObj.linkedTo=targetObj.id;}else if(targetObj.type==='lift'&&['plate','receiver','key','switch'].includes(sourceObj.type)){pushUndo();targetObj.enabledBy=sourceId;}else if(targetObj.type==='teleporter'&&sourceObj.type==='teleporter'){pushUndo();targetObj.linkedTo=sourceId;sourceObj.linkedTo=targetObj.id;}else if(['gate','bridge'].includes(targetObj.type)&&['plate','receiver','key','switch'].includes(sourceObj.type)){pushUndo();if(targetObj.linkedTo&&targetObj.linkedTo!==sourceId){targetObj.linkedToAll=[...new Set([...(targetObj.linkedToAll??[]),targetObj.linkedTo,sourceId])];delete targetObj.linkedTo;}else if(targetObj.linkedToAll){targetObj.linkedToAll=[...new Set([...targetObj.linkedToAll,sourceId])];}else targetObj.linkedTo=sourceId;}else{say('Use plates, receivers, keys or switches for gates and bridges; pair lifts and teleporters with their own type.');return;}level.objects=[structuredClone(player),...structuredClone(objects)];syncEditor();drawBoard();syncConnections();say(`${targetObj.id} connected to ${sourceId}.`);});chip.title=o.type==='lift'?(o.enabledBy?`Enabled by ${o.enabledBy}. Pair it with another lift too.`:'Drop a plate, receiver, key or switch to enable; drop another lift to pair.'):(o.linkedToAll?.length?`Requires all: ${o.linkedToAll.join(' + ')}`:o.linkedTo?`Connected to ${o.linkedTo}. Drop another source to add a required connection.`:'Drop a source here to connect');}return chip;};sources.forEach(o=>sourceWrap.append(makeChip(o,true)));targets.forEach(o=>targetWrap.append(makeChip(o,false)));root.append(sourceWrap,targetWrap);}
function syncEditor(){(document.querySelector<HTMLTextAreaElement>('#jsonEditor')!).value=JSON.stringify(level,null,2);const themeSelect=document.querySelector<HTMLSelectElement>('#environmentTheme');if(themeSelect)themeSelect.value=level.environment.type;syncConnections();updateSelectedObjectNote();updateDirectionReadout();}
async function refreshMusicCatalog(){try{const response=await fetch(`/music/catalog.json?t=${Date.now()}`,{cache:'no-store'});if(response.ok){const parsed=await response.json() as MusicCatalog;musicCatalog=parsed;}}catch{/* Catalog is optional during first startup; the 1-3 fallback remains available. */}}
function attachMusicError(audioElement:HTMLAudioElement){audioElement.addEventListener('error',()=>{if(musicCustom||musicErrorShown)return;musicErrorShown=true;say(`Track not found: ${activeMusicChoice.src}. Add numbered audio files to public/${activeMusicChoice.src.substring(0,activeMusicChoice.src.lastIndexOf('/'))}/ and restart or refresh the dev server.`);});}
async function configureBiomeMusic(){if(musicCustom)return;await refreshMusicCatalog();activeMusicChoice=selectBiomeMusic(level,musicCatalog);if(!musicAudio){musicAudio=new Audio();attachMusicError(musicAudio);}if(!musicAudio.src.endsWith(activeMusicChoice.src)){musicAudio.src=activeMusicChoice.src;musicAudio.loop=true;musicAudio.volume=.45;musicErrorShown=false;}if(musicPlaying)try{await musicAudio.play();}catch{musicPlaying=false;document.querySelector('#musicToggle')!.textContent='Music: off';}}
if(import.meta.hot){import.meta.hot.on('ishibako:music-catalog-updated',()=>{if(!musicCustom)void configureBiomeMusic();});}
if(!musicAudio){musicAudio=new Audio();attachMusicError(musicAudio);}musicAudio.loop=true;musicAudio.volume=.45;
document.querySelector<HTMLInputElement>('#musicInput')!.addEventListener('change',async (e:Event)=>{const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;if(musicAudio)musicAudio.pause();if(musicUrl)URL.revokeObjectURL(musicUrl);musicCustom=true;musicUrl=URL.createObjectURL(file);musicAudio=new Audio(musicUrl);musicAudio.loop=true;musicAudio.volume=.45;attachMusicError(musicAudio);try{await musicAudio.play();musicPlaying=true;document.querySelector('#musicToggle')!.textContent='Music: on';say(`Playing ${file.name} for this session. Biome music resumes when a level is loaded.`);}catch{musicPlaying=false;say('Music loaded. Press the music control to start playback.');}});
document.querySelector('#musicToggle')!.addEventListener('click',async()=>{if(musicPlaying){musicAudio?.pause();musicPlaying=false;document.querySelector('#musicToggle')!.textContent='Music: off';}else{if(!musicCustom)await configureBiomeMusic();try{await musicAudio!.play();musicPlaying=true;document.querySelector('#musicToggle')!.textContent='Music: on';say(musicCustom?'Custom music playing.':`Biome soundtrack: ${activeMusicChoice.folder} track ${activeMusicChoice.track} of ${activeMusicChoice.availableTracks}.`);}catch{musicPlaying=false;document.querySelector('#musicToggle')!.textContent='Music: off';if(!musicCustom)say(`Could not load ${activeMusicChoice.src}. Add audio files to public/music/${activeMusicChoice.folder}/ or use Load music.`);else say('The selected music could not be played. Try an MP3, WAV or OGG file.');}}});
document.querySelector<HTMLSelectElement>('#environmentTheme')!.addEventListener('change',e=>{const select=e.currentTarget as HTMLSelectElement;const oldType=level.environment.type;const nextType=select.value;if(level.environment.musicFolder===undefined||level.environment.musicFolder===oldType)level.environment.musicFolder=nextType;level.environment.type=nextType;drawEnvironment();void configureBiomeMusic();syncEditor();say(`Environment changed to ${nextType}. The puzzle layout is unchanged.`);});
document.querySelector('#downloadRun')!.addEventListener('click',downloadRunRecording);document.querySelector('#closeCompletion')!.addEventListener('click',()=>document.querySelector('#completionModal')!.classList.add('hidden'));document.querySelector('#reset')!.addEventListener('click',()=>{document.querySelector('#completionModal')!.classList.add('hidden');restart();});document.querySelector('#undo')!.addEventListener('click',undo);document.querySelector('#redo')!.addEventListener('click',redo);document.querySelector<HTMLSelectElement>('#editorTool')!.addEventListener('change',e=>{editorMode=(e.target as HTMLSelectElement).value;say(editorMode==='play'?'Play mode.':'Editor tool selected: '+editorMode+'. Click a tile to apply.');});document.querySelector('#soundToggle')!.addEventListener('click',e=>{soundOn=!soundOn;(e.currentTarget as HTMLButtonElement).textContent=`Sound: ${soundOn?'on':'off'}`;if(soundOn)chirp(520,.07);});document.querySelector('#editorToggle')!.addEventListener('click',()=>{const panel=document.querySelector('#editorPanel')!;panel.classList.toggle('hidden');if(!panel.classList.contains('hidden'))syncEditor();else{editorMode='play';document.querySelector<HTMLSelectElement>('#editorTool')!.value='play';}});document.querySelector('#loadJson')!.addEventListener('click',()=>{try{loadLevel(JSON.parse((document.querySelector<HTMLTextAreaElement>('#jsonEditor')!).value));}catch(e){document.querySelector('#validation')!.textContent=`JSON parse error: ${(e as Error).message}`;}});document.querySelector('#downloadJson')!.addEventListener('click',exportJson);document.querySelector('#rotateSelected')!.addEventListener('click',rotateSelectedObject);document.querySelector('#loadShowcase')!.addEventListener('click',()=>{(document.querySelector<HTMLTextAreaElement>('#jsonEditor')!).value=JSON.stringify(showcaseLevel,null,2);loadLevel(showcaseLevel);syncEditor();});document.querySelector<HTMLInputElement>('#fileInput')!.addEventListener('change',async (e:Event)=>{const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;try{const parsed=JSON.parse(await file.text());(document.querySelector<HTMLTextAreaElement>('#jsonEditor')!).value=JSON.stringify(parsed,null,2);document.querySelector('#validation')!.textContent=`Imported ${file.name}. Apply JSON to load it.`;}catch(err){document.querySelector('#validation')!.textContent=`Import failed: ${(err as Error).message}`;}});
window.addEventListener('keydown',e=>{if((e.target as HTMLElement).tagName==='TEXTAREA'||(e.target as HTMLElement).tagName==='INPUT')return;const k=e.key.toLowerCase();if(['w','a','s','d','q','e','r','arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if((e.ctrlKey||e.metaKey)&&k==='z'){e.preventDefault();undo();return;}if((e.ctrlKey||e.metaKey)&&k==='y'){e.preventDefault();redo();return;}if(k==='w'||k==='arrowup')move(screenDirection('w'));if(k==='s'||k==='arrowdown')move(screenDirection('s'));if(k==='a'||k==='arrowleft')move(screenDirection('a'));if(k==='d'||k==='arrowright')move(screenDirection('d'));if(k==='r'&&editorMode!=='play')rotateSelectedObject();if(k==='q')rotateAttached(-1);if(k==='e')rotateAttached(1);if(k==='f')useLift();if(k===' '){attached.clear();drawBoard();say('All blocks detached.');}});
function pointerNdc(e:PointerEvent){const rect=renderer.domElement.getBoundingClientRect();pointer.x=((e.clientX-rect.left)/rect.width)*2-1;pointer.y=-((e.clientY-rect.top)/rect.height)*2+1;raycaster.setFromCamera(pointer,camera);}
function objectAtPointer():{id:string;distance:number}|null{const roots=[...objectMeshes.values()];const hits=raycaster.intersectObjects(roots,true);for(const hit of hits){let node:THREE.Object3D|null=hit.object;while(node&&!node.userData.objectId)node=node.parent;if(node?.userData.objectId)return {id:String(node.userData.objectId),distance:hit.distance};}return null;}
function describeObject(id:string){if(id==='player')return {name:'Player',detail:'Your character',connection:'No connections'};const o=objects.find(x=>x.id===id);if(!o)return null;const names:Record<string,string>={block:'Movable block',plate:'Pressure plate',goal:'Exit',wall:'Wall',lift:'Lift platform',laser:'Laser emitter',mirror:'Laser mirror',bridge:'Retractable bridge',gate:'Gate',switch:'Toggle switch',receiver:'Laser receiver',key:'Collectible key',conveyor:'Conveyor tile',teleporter:'Paired teleporter'};const links:string[]=[];if(o.linkedTo){const target=objects.find(x=>x.id===o.linkedTo);links.push(`Connects to ${target?`${target.id} (${target.type})`:o.linkedTo}`);}if(o.linkedToAll?.length)links.push(`Requires all: ${o.linkedToAll.join(' + ')}`);if(o.enabledBy)links.push(`Enabled by ${o.enabledBy}`);if(o.type==='bridge')links.push(isLinkedMechanismOpen(o,objects)?'Bridge open: gap is walkable':'Bridge closed: gap is impassable');if(o.type==='conveyor')links.push(`Pushes toward ${axialName(DIRS[((o.direction??0)%6+6)%6])}`);if(o.type==='teleporter')links.push('Transfers player and attached blocks to its paired portal');if(o.type==='switch')links.push(`Switch is ${o.active?'on':'off'}`);const linkedBy=objects.filter(x=>x.linkedTo===o.id||x.linkedToAll?.includes(o.id)||x.enabledBy===o.id);for(const source of linkedBy){if(source.enabledBy===o.id)links.push(`Enables ${source.id} (${source.type})`);else if(source.linkedToAll?.includes(o.id))links.push(`Required by ${source.id} (${source.type}, AND connection)`);else links.push(`Connected from ${source.id} (${source.type})`);}if(o.type==='block'){links.push(attached.has(o.id)?'Attached to player · click to detach':(hexDistance(player,o)===1&&player.h===o.h?'Adjacent · click to attach':'Move adjacent to attach'));if(o.assemblyId)links.push(`Glued assembly: ${o.assemblyId}`);}if(o.type==='laser'||o.type==='mirror')links.push(`Direction: ${axialName(DIRS[((o.direction??0)%6+6)%6])}`);if(o.type==='key')links.push(o.active?'Already collected':'Collectible');if(o.type==='gate'){links.push(isGateOpen(o)?'Currently open':'Currently closed');if(o.requiresKey)links.push('Requires a collected key');}return {name:names[o.type]||o.type,detail:`${o.id} · hex (${o.q}, ${o.r}) · height ${o.h}`,connection:links.join(' · ')||'No connections'};}
renderer.domElement.addEventListener('pointermove',(e:PointerEvent)=>{pointerNdc(e);const found=objectAtPointer();if(!found){tooltip.classList.add('hidden');renderer.domElement.style.cursor='';return;}const info=describeObject(found.id);if(!info){tooltip.classList.add('hidden');return;}tooltip.replaceChildren();const title=document.createElement('strong');title.textContent=info.name;const detail=document.createElement('span');detail.textContent=info.detail;const connection=document.createElement('small');connection.textContent=info.connection;tooltip.append(title,detail,connection);tooltip.classList.remove('hidden');const stageRect=renderer.domElement.closest('.stage')!.getBoundingClientRect();tooltip.style.left=`${Math.min(stageRect.width-270,Math.max(12,e.clientX-stageRect.left+14))}px`;tooltip.style.top=`${Math.min(stageRect.height-92,Math.max(12,e.clientY-stageRect.top+14))}px`;renderer.domElement.style.cursor=found.id!=='player'?'pointer':'';});
renderer.domElement.addEventListener('pointerleave',()=>{tooltip.classList.add('hidden');renderer.domElement.style.cursor='';});
renderer.domElement.addEventListener('pointerdown',(e:PointerEvent)=>{pointerNdc(e);const editorVisible=!document.querySelector('#editorPanel')!.classList.contains('hidden');const hitObject=objectAtPointer();if(hitObject){if(editorVisible){selectedObjectId=hitObject.id;updateSelectedObjectNote();syncConnections();return;}const obj=objects.find(x=>x.id===hitObject.id);if(obj?.type==='block'){toggleAttach(obj.id);return;}return;}if(editorVisible&&editorMode!=='play'){const hits=raycaster.intersectObjects(world.children,true);for(const hit of hits){let node:THREE.Object3D|null=hit.object;while(node&&!node.userData.cell)node=node.parent;if(node?.userData.cell){editorCell=node.userData.cell as Hex;applyEditorTool(editorCell);return;}}}});
function resize(){const w=viewport.clientWidth,h=viewport.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/Math.max(1,h);camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(viewport);resize();configureBiomeMusic();recordRunFrame('start');drawBoard();drawEnvironment();fitCamera();
function animate(t:number){requestAnimationFrame(animate);controls.update();const time=t*.001;const now=performance.now();for(const [id,tw] of positionTweens){const g=objectMeshes.get(id);if(!g){positionTweens.delete(id);continue;}const raw=Math.min(1,(now-tw.start)/tw.duration);const eased=raw*raw*(3-2*raw);g.position.lerpVectors(tw.from,tw.to,eased);g.position.y+=Math.sin(raw*Math.PI)*.12;if(raw>=1)positionTweens.delete(id);}for(const [id,g] of objectMeshes){const o=objects.find(o=>o.id===id);if(o?.type==='goal'&&!positionTweens.has(id))g.position.y=hexWorld(o).y+Math.sin(time*2)*.055;if(o?.type==='plate'){const ring=plateRings.get(id);if(ring)ring.rotation.z=time*.3;}if(o?.type==='receiver'){g.rotation.y=Math.sin(time*1.7)*.06;}if(o?.type==='lift'){g.position.y=hexWorld(o).y+Math.sin(time*1.8+o.q)*.025;}}for(const mote of scenery.children){if(mote.userData.floatPhase!==undefined){mote.position.y=Number(mote.userData.baseY)+Math.sin(time*1.15+Number(mote.userData.floatPhase))*.12;mote.scale.setScalar(.85+(.15*Math.sin(time*2+Number(mote.userData.floatPhase))));}}const pg=objectMeshes.get('player');if(pg&&!positionTweens.has('player')){const p=hexWorld(player);pg.position.y=p.y+Math.sin(time*3)*.035;pg.rotation.y=Math.sin(time*1.3)*.035;}if(performance.now()-lastToast>3600)toast.classList.remove('show');renderer.render(scene,camera);}requestAnimationFrame(animate);
